"""Apply to a supplied Godot directory; no implicit production mutation."""
from pathlib import Path
import json,sys,difflib
root=Path(sys.argv[1]); here=Path(__file__).parent
changes={}
def edit(name,old,new,count=1):
 p=root/'scripts'/name
 text=changes.get(p,p.read_text())
 if old not in text: raise SystemExit('missing anchor '+name+' '+repr(old[:100]))
 changes[p]=text.replace(old,new,count)
