patch=[]
for p,text in changes.items():
 patch.extend(difflib.unified_diff(p.read_text().splitlines(True),text.splitlines(True),fromfile='a/godot/scripts/'+str(p.relative_to(root/'scripts')),tofile='b/godot/scripts/'+str(p.relative_to(root/'scripts'))))
 p.write_text(text)
(here/'integration.patch').write_text(''.join(patch))
p=root/'content/verified_rules.json'; current=json.loads(p.read_text()); overlay=json.loads((here/'overlay.json').read_text())
current['sources'] += overlay['sources']
for kind in ['units','cards']: current[kind].update(overlay[kind])
p.write_text(json.dumps(current,ensure_ascii=False,indent=2)+'\n')
print('Integrated',len(changes),'files in',root)
